"""Bundle src/ into one ModuleScript. Requires only Python's standard library."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def build(output: Path) -> None:
    manifest = json.loads((ROOT / "tools/manifest.json").read_text())
    notices = (ROOT / "LICENSE").read_text() + "\n" + (ROOT / "THIRD_PARTY_NOTICES.md").read_text()
    assert "]====]" not in notices
    parts = [
        "-- Bloomware UI 1.5.0\n",
        "-- Generated by tools/build.py. Editable modules are in src/.\n",
        "-- MIT license; see LICENSE and the notices included below.\n",
        "--[====[\n" + notices + "\n]====]\n",
        "local moduleFactories = {}\n",
    ]
    for item in manifest:
        source_path = ROOT / "src" / item["file"]
        source = source_path.read_text().rstrip()
        parts.append("\n-- " + item["file"] + "\n")
        parts.append("moduleFactories[" + json.dumps(item["name"]) + "] = function(script, require)\n")
        parts.append(source + "\nend\n")
    parts.append("\n" + (ROOT / "tools/loader.lua").read_text())
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text("".join(parts))
    print(f"Built {output.name} ({output.stat().st_size:,} bytes)")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", nargs="?", type=Path, default=ROOT / "BloomwareUI.lua")
    build(parser.parse_args().output.resolve())
